      content: '<div class="not-content my-6">\n  <ResizableDemo client:load />\n</div>\n\n## Installation\n\n<PackageInstall />\n\n## Usage\n\n```tsx\n<ResizablePanelGroup orientation="horizontal">\n  <ResizablePanel defaultSize={50} minSize={30}>\n    Left panel\n  </ResizablePanel>\n  <ResizableHandle />\n  <ResizablePanel defaultSize={50} minSize={30}>\n    Right panel\n  </ResizablePanel>\n</ResizablePanelGroup>\n\n<ResizablePanelGroup orientation="vertical" onLayout={(sizes) => console.log(sizes)}>\n  <ResizablePanel size={topPanelSize} onResize={setTopPanelSize}>\n    Top\n  </ResizablePanel>\n  <ResizableHandle withHandle />\n  <ResizablePanel>\n    Bottom\n  </ResizablePanel>\n</ResizablePanelGroup>\n```\n\n## API Reference\n\n### ResizablePanelGroup\n\n<div class="not-content">\n  <PropSpec\n    client:load\n    rows={[\n    { prop: "orientation", default: "\\"horizontal\\"", type: "\\"horizontal\\" | \\"vertical\\"", description: "Split direction." },\n    { prop: "onLayout", default: "\u2014", type: "(sizes: number[]) => void", description: "Fires after resize with panel sizes (percentages summing to ~100)." }\n    ]}\n  />\n</div>\n### ResizablePanel\n\n<div class="not-content">\n  <PropSpec\n    client:load\n    rows={[\n    { prop: "defaultSize", default: "50", type: "number", description: "Initial size as percentage." },\n    { prop: "minSize", default: "10", type: "number", description: "Minimum size percentage." },\n    { prop: "maxSize", default: "100", type: "number", description: "Maximum size percentage." },\n    { prop: "size", default: "\u2014", type: "number", description: "Controlled size percentage." },\n    { prop: "onResize", default: "\u2014", type: "(size: number) => void", description: "Event handler when panel resizes." }\n    ]}\n  />\n</div>\n### ResizableHandle\n\n<div class="not-content">\n  <PropSpec\n    client:load\n    rows={[\n    { prop: "withHandle", default: "false", type: "boolean", description: "Shows grip affordance on separator." },\n    { prop: "disabled", default: "false", type: "boolean", description: "Disables resizing." }\n    ]}\n  />\n</div>',
