      slug: "components/tooltip",
      href: "/components/tooltip/",
      title: "Tooltip",
      description: "Contextual text popup on hover or focus.",
      category: "components",
      content: '<div class="not-content my-6">\n  <TooltipDemo client:load />\n</div>\n\n## Installation\n\n<PackageInstall />\n\n## Usage\n\n```tsx\n<Tooltip trigger={<Button>Hover me</Button>} content="Helpful tooltip text" />\n\n<Tooltip\n  trigger={<IconButton icon="info" />}\n  content="Extended information"\n  position="Top"\n  align="Center"\n/>\n```\n\n## API Reference\n\n<div class="not-content">\n  <PropSpec\n    client:load\n    rows={[\n    { prop: "trigger", default: "\u2014", type: "ReactNode", description: "Element that triggers the tooltip (required)." },\n    { prop: "content", default: "\u2014", type: "ReactNode", description: "Tooltip content (required)." },\n    { prop: "position", default: "\\"Top\\"", type: "\\"Top\\" | \\"Left\\" | \\"Bottom\\" | \\"Right\\"", description: "Position relative to trigger." },\n    { prop: "align", default: "\\"Center\\"", type: "\\"Start\\" | \\"Center\\" | \\"End\\"", description: "Alignment along the edge." },\n    { prop: "delayMs", default: "700", type: "number", description: "Delay before showing (milliseconds)." },\n    { prop: "open", default: "\u2014", type: "boolean", description: "Controlled open state." },\n    { prop: "defaultOpen", default: "\u2014", type: "boolean", description: "Uncontrolled initial open state." },\n    { prop: "onOpenChange", default: "\u2014", type: "(open: boolean) => void", description: "Event handler when open state changes." }\n    ]}\n  />\n</div>',
      searchText: 'tooltip contextual text popup on hover or focus. \n<div class="not-content my-6">\n  <tooltipdemo client:load />\n</div>\n\n## installation\n\n<packageinstall />\n\n## usage\n\n```tsx\n<tooltip trigger={<button>hover me</button>} content="helpful tooltip text" />\n\n<tooltip\n  trigger={<iconbutton icon="info" />}\n  content="extended information"\n  position="top"\n  align="center"\n/>\n```\n\n## api reference\n\n<div class="not-content">\n  <propspec\n    client:load\n    rows={[\n    { prop: "trigger", default: "\u2014", type: "reactnode", description: "element that triggers the tooltip (required)." },\n    { prop: "content", default: "\u2014", type: "reactnode", description: "tooltip content (required)." },\n    { prop: "position", default: "\\"top\\"", type: "\\"top\\" | \\"left\\" | \\"bottom\\" | \\"right\\"", description: "position relative to trigger." },\n    { prop: "align", default: "\\"center\\"", type: "\\"start\\" | \\"center\\" | \\"end\\"", description: "alignment along the edge." },\n    { prop: "delayms", default: "700", type: "number", description: "delay before showing (milliseconds)." },\n    { prop: "open", default: "\u2014", type: "boolean", description: "controlled open state." },\n    { prop: "defaultopen", default: "\u2014", type: "boolean", description: "uncontrolled initial open state." },\n    { prop: "onopenchange", default: "\u2014", type: "(open: boolean) => void", description: "event handler when open state changes." }\n    ]}\n  />\n</div>\n'
