// src/docs-store.ts
import { SEMANTIC_TEXT } from "@refineui/tokens";
var index = docs_index_default;
var TOKEN_CATEGORIES = [
  "colors",
  "typography",
  "spacing",
  "sizing",
  "radius",
  "stroke",
  "shadows",
  "motion",
  "zIndex"
];
function normalizeSlug(input) {
  return input.trim().replace(/^https?:\/\/[^/]+/i, "").replace(/^\//, "").replace(/\/$/, "");
}
function getLlmIndex() {
  return index.llmIndex;
}
function listPages(category) {
  return index.pages.filter((page) => category ? page.category === category : true).map(({ slug, href, title, description, category: pageCategory }) => ({
    slug,
    href,
    title,
    description,
    category: pageCategory
  }));
}
function getDocPage(slugInput) {
  const slug = normalizeSlug(slugInput);
  const page = index.pages.find((item) => item.slug === slug);
  if (!page) return null;
  const { searchText, ...doc } = page;
  void searchText;
  return doc;
}
function searchDocs(query, category, limit = 10) {
  const terms = query.toLowerCase().split(/\s+/).map((term) => term.trim()).filter(Boolean);
  if (terms.length === 0) {
    return listPages(category).slice(0, limit);
  }
  const scored = index.pages.filter((page) => category ? page.category === category : true).map((page) => {
    let score = 0;
    for (const term of terms) {
      if (page.slug.includes(term)) score += 4;
      if (page.title.toLowerCase().includes(term)) score += 3;
      if (page.description.toLowerCase().includes(term)) score += 2;
      if (page.searchText.includes(term)) score += 1;
    }
    return { page, score };
  }).filter(({ score }) => score > 0).sort((a, b) => b.score - a.score).slice(0, limit);
  return scored.map(({ page }) => ({
    slug: page.slug,
    href: page.href,
    title: page.title,
    description: page.description,
    category: page.category
  }));
}
function listTokenCategories() {
  return [...TOKEN_CATEGORIES];
}
function listSemanticTextRoles() {
  return Object.keys(SEMANTIC_TEXT);
}
function getIndexMeta() {
  return {
    generatedAt: index.generatedAt,
    pageCount: index.pages.length
  };
}

export {
  DESIGN_RULES,
  normalizeSlug,
  getLlmIndex,
  listPages,
  getDocPage,
  searchDocs,
  listTokenCategories,
  listSemanticTextRoles,
  getIndexMeta
};
